{"q": "العبارة «ناتج المقدار (1 − 2√3)² يساوي 11» هي:", "opts": ["غلط، والناتج الصحيح 13 − 4√3", "صح، والناتج 11", "غلط، والناتج الصحيح −11", "غلط، والناتج الصحيح 13 + 4√3"], "corr": 0, "exp": "(1 − 2√3)² = 1 − 4√3 + 12 = 13 − 4√3، وهو لا يساوي 11.", "c": "2025", "k": "powers"},
{"q": "العبارة «ضعف العدد 2⁵ يساوي 2⁶» هي:", "opts": ["صح، لأن 2 × 2⁵ = 2⁶", "غلط، لأن 2 × 2⁵ = 2¹⁰", "غلط، لأن 2 × 2⁵ = 4⁵", "غلط، لأن 2 × 2⁵ = 2⁵"], "corr": 0, "exp": "ضعف العدد = 2 × 2⁵ = 2¹ × 2⁵ = 2⁶، فالعبارة صحيحة.", "c": "2025", "k": "powers"},
{"q": "العبارة «يوجد عددان صورة كل منهما 4 وفق التابع f(x) = x²» هي:", "opts": ["صح، وهما 2 و −2", "غلط، لأنه يوجد عدد واحد فقط", "غلط، لأنه لا يوجد أي عدد", "غلط، لأنه يوجد أربعة أعداد"], "corr": 0, "exp": "نحل f(x) = 4: x² = 4 ⟹ x = 2 أو x = −2، فالعبارة صحيحة.", "c": "2025", "k": "functions"},
{"q": "العبارة التي تُكمل المتطابقة (3y − .....)² = ...... + ..... + 1 هي:", "opts": ["(3y − 1)² = 9y² − 6y + 1", "(3y − 1)² = 9y² + 6y + 1", "(3y − 1)² = 3y² − 6y + 1", "(3y − 2)² = 9y² − 12y + 1"], "corr": 0, "exp": "الحد الأخير 1 = 1²، فالعدد داخل القوس هو 1، ومنه (3y − 1)² = 9y² − 2 × 3y × 1 + 1 = 9y² − 6y + 1.", "c": "2025", "k": "factor"},
{"q": "إذا كان −3x > 15 فإن x ...... −5 (الرمز الصحيح للفراغ):", "opts": ["x < −5", "x > −5", "x ≤ −5", "x ≥ −5"], "corr": 0, "exp": "بقسمة الطرفين على العدد السالب −3 يتغير اتجاه المتراجحة: x < 15 ÷ (−3) = −5.", "c": "2025", "k": "equations"},
{"q": "أسطوانة دورانية ارتفاعها h = 6 cm ونصف قطر قاعدتها r = 4 cm، فإن حجمها بوحدة cm³ يساوي:", "opts": ["96π", "48π", "24π", "144π"], "corr": 0, "exp": "V = π × r² × h = π × 16 × 6 = 96π cm³.", "c": "2025", "k": "solids"},
{"q": "القاسم المشترك الأكبر GCD(180 , 18) يساوي:", "opts": ["18", "9", "6", "180"], "corr": 0, "exp": "180 = 18 × 10، فالعدد 18 يقسم 180 ويقسم نفسه، وهو أكبر قاسم للعدد 18، إذن GCD = 18.", "c": "2025", "k": "powers"},
{"q": "ليكن التابع f المعرّف وفق العلاقة f(x) = x² − x − 6. قيمة f(−1) تساوي:", "opts": ["−4", "−6", "4", "−8"], "corr": 0, "exp": "f(−1) = (−1)² − (−1) − 6 = 1 + 1 − 6 = −4.", "c": "2025", "k": "functions"},
{"q": "ليكن التابع f المعرّف وفق العلاقة f(x) = x² − x − 6. قيمة f(½) تساوي:", "opts": ["−25/4", "−6", "−23/4", "25/4"], "corr": 0, "exp": "f(½) = ¼ − ½ − 6 = ¼ − 2/4 − 24/4 = −25/4.", "c": "2025", "k": "functions"},
{"q": "ليكن التابع f المعرّف وفق العلاقة f(x) = x² − x − 6. أسلاف العدد (−6) هي:", "opts": ["0 و 1", "0 و −1", "6 و −1", "2 و −3"], "corr": 0, "exp": "نحل f(x) = −6: x² − x − 6 = −6 ⟹ x² − x = 0 ⟹ x(x − 1) = 0 ⟹ x = 0 أو x = 1.", "c": "2025", "k": "functions"},
{"q": "نشر المقدار A = (x − 3)(x + 2) يعطي:", "opts": ["x² − x − 6", "x² + x − 6", "x² − 5x − 6", "x² − x + 6"], "corr": 0, "exp": "(x − 3)(x + 2) = x² + 2x − 3x − 6 = x² − x − 6، وهو يساوي f(x) حيث f(x) = x² − x − 6.", "c": "2025", "k": "factor"},
{"q": "حل المعادلة f(x) = 0 حيث f(x) = x² − x − 6 = (x − 3)(x + 2) هو:", "opts": ["x = 3 أو x = −2", "x = −3 أو x = 2", "x = 3 أو x = 2", "x = −3 أو x = −2"], "corr": 0, "exp": "(x − 3)(x + 2) = 0 ⟹ x − 3 = 0 أو x + 2 = 0 ⟹ x = 3 أو x = −2.", "c": "2025", "k": "equations"},
{"q": "كيس فيه 10 كرات متماثلة مرقمة بالأرقام (1 , 1 , 1 , 1 , 2 , 3 , 3 , 4 , 4 , 4)، تُسحب منه كرة عشوائياً ويُقرأ الرقم المسجل عليها. احتمالات ظهور الأرقام 1 و 2 و 3 و 4 على الترتيب (على فروع شجرة الإمكانات) هي:", "opts": ["4/10 , 1/10 , 2/10 , 3/10", "1/4 , 1/4 , 1/4 , 1/4", "3/10 , 2/10 , 1/10 , 4/10", "4/10 , 2/10 , 1/10 , 3/10"], "corr": 0, "exp": "عدد الكرات 10: أربع كرات تحمل 1 وكرة واحدة تحمل 2 وكرتان تحملان 3 وثلاث كرات تحمل 4، ومجموع الاحتمالات = 10/10 = 1.", "c": "2025", "k": "stats"},
{"q": "كيس فيه 10 كرات متماثلة مرقمة بالأرقام (1 , 1 , 1 , 1 , 2 , 3 , 3 , 4 , 4 , 4)، تُسحب منه كرة عشوائياً ويُقرأ الرقم المسجل عليها. احتمال الحدث A: «سحب كرة تحمل رقماً أصغر تماماً من 4» يساوي:", "opts": ["7/10", "3/10", "4/10", "6/10"], "corr": 0, "exp": "الأرقام الأصغر تماماً من 4 هي 1 و 2 و 3 وعدد الكرات التي تحملها 4 + 1 + 2 = 7، فـ P(A) = 7/10.", "c": "2025", "k": "stats"},
{"q": "كيس فيه 10 كرات متماثلة مرقمة بالأرقام (1 , 1 , 1 , 1 , 2 , 3 , 3 , 4 , 4 , 4)، تُسحب منه كرة عشوائياً ويُقرأ الرقم المسجل عليها. احتمال الحدث المعاكس A′ للحدث A: «سحب كرة تحمل رقماً أصغر تماماً من 4» يساوي:", "opts": ["3/10", "7/10", "4/10", "1"], "corr": 0, "exp": "P(A′) = 1 − P(A) = 1 − 7/10 = 3/10 (وهو احتمال سحب كرة تحمل الرقم 4).", "c": "2025", "k": "stats"},
{"q": "المدى للعينة S = (1 , 1 , 1 , 1 , 2 , 3 , 3 , 4 , 4 , 4) يساوي:", "opts": ["3", "4", "2.5", "1"], "corr": 0, "exp": "المدى = أكبر قيمة − أصغر قيمة = 4 − 1 = 3.", "c": "2025", "k": "stats"},
{"q": "الوسيط للعينة S = (1 , 1 , 1 , 1 , 2 , 3 , 3 , 4 , 4 , 4) يساوي:", "opts": ["2.5", "2", "3", "2.2"], "corr": 0, "exp": "القيم مرتبة، وعددها 10 (زوجي)، فالوسيط هو وسط القيمتين الخامسة (2) والسادسة (3): (2 + 3) ÷ 2 = 2.5.", "c": "2025", "k": "stats"},
{"q": "المثلث ORF قائم في F حيث FO = 2، والمثلث OMN قائم في N حيث OM = x + 4 و MN = x و ON = 8 (النقاط F و O و N على استقامة واحدة). المعادلة التي نحصل عليها بتطبيق مبرهنة فيثاغورث في المثلث OMN هي:", "opts": ["(x + 4)² = x² + 8²", "(x + 4)² = x² − 8²", "x² = (x + 4)² + 8²", "(x + 4)² + x² = 8²"], "corr": 0, "exp": "OM هو الوتر في المثلث القائم OMN، فـ OM² = MN² + ON² أي (x + 4)² = x² + 64.", "c": "2025", "k": "triangle"},
{"q": "المثلث ORF قائم في F حيث FO = 2، والمثلث OMN قائم في N حيث OM = x + 4 و MN = x و ON = 8 (النقاط F و O و N على استقامة واحدة). قيمة x تساوي:", "opts": ["6", "4", "8", "12"], "corr": 0, "exp": "(x + 4)² = x² + 64 ⟹ x² + 8x + 16 = x² + 64 ⟹ 8x = 48 ⟹ x = 6.", "c": "2025", "k": "triangle"},
{"q": "المثلث ORF قائم في F حيث FO = 2، والمثلث OMN قائم في N حيث OM = x + 4 و MN = x و ON = 8 (النقاط F و O و N على استقامة واحدة). المستقيمان (MN) و (FR) متوازيان لأن:", "opts": ["كلاً منهما عمودي على المستقيم (FN)", "FR = MN", "المثلثان ORF و OMN متطابقان", "OF = ON"], "corr": 0, "exp": "(FR) ⟂ (FN) في المثلث القائم ORF و (MN) ⟂ (FN) في المثلث القائم OMN، والمستقيمان العموديان على مستقيم واحد متوازيان.", "c": "2025", "k": "triangle"},
{"q": "المثلث ORF قائم في F حيث FO = 2، والمثلث OMN قائم في N حيث OM = x + 4 و MN = x و ON = 8 (النقاط F و O و N على استقامة واحدة). طول OR يساوي (علماً أن x = 6 و (MN) // (FR)):", "opts": ["2.5", "5", "4", "3"], "corr": 0, "exp": "بما أن MN // FR فالنسب متساوية: OF/ON = OR/OM = FR/MN. OF/ON = 2/8 = ¼ و OM = 10، فـ OR = 10 × ¼ = 2.5.", "c": "2025", "k": "triangle"},
{"q": "المثلث ORF قائم في F حيث FO = 2، والمثلث OMN قائم في N حيث OM = x + 4 و MN = x و ON = 8 (النقاط F و O و N على استقامة واحدة). طول FR يساوي (علماً أن x = 6 و (MN) // (FR)):", "opts": ["1.5", "2", "3", "1"], "corr": 0, "exp": "من تناسب أضلاع المثلثين المتشابهين: FR/MN = OF/ON = ¼ ⟹ FR = 6 × ¼ = 1.5.", "c": "2025", "k": "triangle"},
{"q": "المثلث ORF قائم في F حيث FO = 2، والمثلث OMN قائم في N حيث OM = x + 4 و MN = x و ON = 8 (النقاط F و O و N على استقامة واحدة). إذا كانت H المسقط القائم للنقطة N على المستقيم (OM) وكان x = 6، فإن طول NH يساوي:", "opts": ["4.8", "6", "3.2", "5"], "corr": 0, "exp": "sin Ô في المثلث OHN = NH / ON، وفي المثلث OMN = MN / OM = 6/10. إذن NH / 8 = 6/10 ⟹ NH = 4.8.", "c": "2025", "k": "triangle"},
{"q": "مخروط دوراني ارتفاعه SO₁ = 12 cm ونصف قطر قاعدته O₁A = 6 cm، قُطع بمستوٍ يوازي قاعدته ويبعد عنها 4 cm، فقطع [SO₁] في O₂ والجانبي [SA] في N. حجم المخروط الذي مركز قاعدته O₁ يساوي:", "opts": ["144π", "432π", "48π", "72π"], "corr": 0, "exp": "V = ⅓ × π × r² × h = ⅓ × π × 36 × 12 = 144π cm³.", "c": "2025", "k": "solids"},
{"q": "مخروط دوراني ارتفاعه SO₁ = 12 cm ونصف قطر قاعدته O₁A = 6 cm، قُطع بمستوٍ يوازي قاعدته ويبعد عنها 4 cm، فقطع [SO₁] في O₂ والجانبي [SA] في N. طول O₂N يساوي:", "opts": ["4 cm", "3 cm", "6 cm", "2 cm"], "corr": 0, "exp": "SO₂ = 12 − 4 = 8. المستوي يوازي القاعدة فالمثلثان SO₂N و SO₁A متشابهان: O₂N / O₁A = SO₂ / SO₁ = 8/12 ⟹ O₂N = 6 × 8/12 = 4.", "c": "2025", "k": "solids"},
{"q": "مخروط دوراني ارتفاعه SO₁ = 12 cm ونصف قطر قاعدته O₁A = 6 cm، قُطع بمستوٍ يوازي قاعدته ويبعد عنها 4 cm، فقطع [SO₁] في O₂ والجانبي [SA] في N. نكتب SA = √180 بالصيغة a√5، فإن a تساوي:", "opts": ["6", "5", "3", "12"], "corr": 0, "exp": "SA² = SO₁² + O₁A² = 144 + 36 = 180، و √180 = √(36 × 5) = 6√5، إذن a = 6.", "c": "2025", "k": "solids"},
{"q": "مخروط دوراني ارتفاعه SO₁ = 12 cm ونصف قطر قاعدته O₁A = 6 cm، قُطع بمستوٍ يوازي قاعدته ويبعد عنها 4 cm، فقطع [SO₁] في O₂ والجانبي [SA] في N. قيمة sin(∠SAO₁) تساوي:", "opts": ["2√5/5", "√5/5", "1/2", "√5/2"], "corr": 0, "exp": "sin(∠SAO₁) = SO₁ / SA = 12 / (6√5) = 2/√5 = 2√5/5.", "c": "2025", "k": "solids"},
{"q": "لتكن جملة المعادلتين d: x − 2y = 0 و Δ: 2x − y = 6. حل الجملة هو:", "opts": ["(x , y) = (4 , 2)", "(x , y) = (2 , 4)", "(x , y) = (−4 , −2)", "(x , y) = (4 , −2)"], "corr": 0, "exp": "من d: x = 2y، نعوض في Δ: 4y − y = 6 ⟹ y = 2 ثم x = 4. وهما إحداثيا نقطة تقاطع المستقيمين M(4 , 2).", "c": "2025", "k": "equations"},
{"q": "إحداثيا النقطة A نقطة تقاطع المستقيم Δ: 2x − y = 6 مع محور التراتيب Oy هما:", "opts": ["A(0 , −6)", "A(0 , 6)", "A(3 , 0)", "A(−6 , 0)"], "corr": 0, "exp": "على محور التراتيب x = 0، فيكون −y = 6 أي y = −6، إذن A(0 , −6).", "c": "2025", "k": "functions"},
{"q": "إذا كانت O(0 , 0) و A(0 , −6) و M(4 , 2)، فإن مساحة المثلث OAM بوحدة المساحة تساوي:", "opts": ["12", "24", "6", "10"], "corr": 0, "exp": "نأخذ القاعدة OA = 6 على محور التراتيب، والارتفاع المقابل = بعد M عن المحور = 4. المساحة = ½ × 6 × 4 = 12.", "c": "2025", "k": "triangle"},
{"q": "دائرة مركزها O ونصف قطرها OA = 6، ABCD نصف مسدس منتظم مرسوم داخلها (AD قطر)، و DX مماس للدائرة في D، والمستقيم (OC) يقطع المماس في M. المثلث ABD قائم في B لأن:", "opts": ["B نقطة من الدائرة التي قطرها AD", "AB = BD", "AB = 6", "∠BAD = 60°"], "corr": 0, "exp": "كل مثلث مرسوم داخل دائرة وأحد أضلاعه قطر لها يكون قائماً في الرأس المقابل لهذا القطر، فالمثلث ABD قائم في B.", "c": "2025", "k": "circle"},
{"q": "دائرة مركزها O ونصف قطرها OA = 6، ABCD نصف مسدس منتظم مرسوم داخلها (AD قطر)، و DX مماس للدائرة في D، والمستقيم (OC) يقطع المماس في M. قياسات زوايا المثلث OMD هي:", "opts": ["∠DOM = 60° ، ∠ODM = 90° ، ∠OMD = 30°", "∠DOM = 30° ، ∠ODM = 90° ، ∠OMD = 60°", "∠DOM = 45° ، ∠ODM = 90° ، ∠OMD = 45°", "∠DOM = 60° ، ∠ODM = 60° ، ∠OMD = 60°"], "corr": 0, "exp": "المثلث OCD متساوي الأضلاع (OC = OD = CD = 6) فـ ∠DOC = ∠DOM = 60°. المماس DM عمودي على نصف القطر OD فـ ∠ODM = 90°، وبالتالي ∠OMD = 180° − 60° − 90° = 30°.", "c": "2025", "k": "circle"},
{"q": "دائرة مركزها O ونصف قطرها OA = 6، ABCD نصف مسدس منتظم مرسوم داخلها (AD قطر)، و DX مماس للدائرة في D، والمستقيم (OC) يقطع المماس في M. المثلث DCM متساوي الساقين لأن:", "opts": ["∠CDM = ∠CMD = 30°", "∠DCM = 60°", "DC = DM", "∠CDM = 90°"], "corr": 0, "exp": "∠CDM = ∠ODM − ∠ODC = 90° − 60° = 30° و ∠CMD = ∠OMD = 30°، فالمثلث DCM متساوي الساقين رأسه C.", "c": "2025", "k": "circle"},
{"q": "دائرة مركزها O ونصف قطرها OA = 6، ABCD نصف مسدس منتظم مرسوم داخلها (AD قطر)، و DX مماس للدائرة في D، والمستقيم (OC) يقطع المماس في M. طول CM يساوي:", "opts": ["6", "12", "6√3", "3"], "corr": 0, "exp": "المثلث DCM متساوي الساقين فـ CM = CD = 6. (تحقق: في المثلث OMD cos 60° = OD/OM ⟹ OM = 12، و CM = OM − OC = 12 − 6 = 6).", "c": "2025", "k": "circle"},
{"q": "دائرة مركزها O ونصف قطرها OA = 6، ABCD نصف مسدس منتظم مرسوم داخلها (AD قطر)، و DX مماس للدائرة في D، والمستقيم (OC) يقطع المماس في M. الرباعي OBMD رباعي دائري لأن:", "opts": ["الزاويتين ∠OBM و ∠ODM قائمتان وتحصران القطعة OM", "∠BOD = ∠BMD", "أضلاعه متساوية", "قطراه متعامدان"], "corr": 0, "exp": "∠ODM = 90° لأن DM مماس. وفي المثلث OBM: CB = CO = CM = 6 أي أن B تقع على الدائرة التي قطرها OM، فـ ∠OBM = 90°. الزاويتان القائمتان تحصران OM فالرباعي دائري.", "c": "2025", "k": "circle"},
{"q": "دائرة مركزها O ونصف قطرها OA = 6، ABCD نصف مسدس منتظم مرسوم داخلها (AD قطر)، و DX مماس للدائرة في D، والمستقيم (OC) يقطع المماس في M. مركز الدائرة المارة برؤوس الرباعي OBMD ونصف قطرها هما:", "opts": ["C ، 6", "منتصف OD ، 3", "B ، 6", "O ، 12"], "corr": 0, "exp": "الدائرة المارة برؤوس OBMD قطرها OM (للزاويتين القائمتين)، فمركزها منتصف [OM] وهو C، ونصف قطرها OM ÷ 2 = 12 ÷ 2 = 6.", "c": "2025", "k": "circle"},
{"q": "ABC مثلث قائم في A ومتساوي الساقين، عندئذ sin B تساوي:", "opts": ["√2/2", "√3/2", "1/2", "√3/3"], "corr": 0, "exp": "المثلث قائم ومتساوي الساقين، فزاويتا القاعدة قياس كل منهما 45°، إذن sin B = sin 45° = √2/2.", "c": "2024", "k": "triangle"},
{"q": "العددان الأوليان فيما بينهما في كل زوج من الأزواج المعطاة هو:", "opts": ["(55 , 9)", "(55 , 11)", "(55 , 5)", "(55 , 121)"], "corr": 0, "exp": "55 = 5 × 11 و 9 = 3²، ولا يوجد قاسم مشترك بينهما غير 1، فالقاسم المشترك الأكبر 1. أما الأزواج الأخرى فقاسمها المشترك الأكبر 11 أو 5.", "c": "2024", "k": "powers"},
{"q": "طبيعة العدد (1 − √2)² هي:", "opts": ["غير عادي", "عادي", "صحيح", "عشري"], "corr": 0, "exp": "(1 − √2)² = 1 − 2√2 + 2 = 3 − 2√2، وبما أن √2 عدد غير عادي فإن الناتج غير عادي.", "c": "2024", "k": "powers"},
{"q": "مسدس منتظم مرسوم داخل دائرة نصف قطرها 3 cm، فإن محيط المسدس يساوي:", "opts": ["18 cm", "27 cm", "12 cm", "9 cm"], "corr": 0, "exp": "طول ضلع المسدس المنتظم المرسوم داخل دائرة يساوي نصف قطرها = 3 cm، فالمحيط = 6 × 3 = 18 cm.", "c": "2024", "k": "circle"},
{"q": "في الشكل المرسوم AECDBHGF متوازي مستطيلات فيه ABC قائم في A، و HE = 1 و EC = 4 و HB = 3. العبارة «حجم متوازي المستطيلات يساوي 24» هي:", "opts": ["غلط، والحجم الصحيح 12", "صح، والحجم 24", "غلط، والحجم الصحيح 8", "غلط، والحجم الصحيح 36"], "corr": 0, "exp": "الحجم = 4 × 3 × 1 = 12، فالعبارة خاطئة.", "c": "2024", "k": "solids"},
{"q": "في الشكل المرسوم AECDBHGF متوازي مستطيلات فيه ABC قائم في A، و HE = 1 و EC = 4 و HB = 3. العبارة «الحرف [EH] يوازي الوجه CDFG» هي:", "opts": ["صح", "غلط لأنه يقطع الوجه CDFG", "غلط لأنه عمودي على الوجه CDFG", "غلط لأنه يقع داخل الوجه CDFG"], "corr": 0, "exp": "الحرف EH يوازي الحرف CG الذي ينتمي إلى الوجه CDFG، وهو لا يقطعه، فهو يوازي هذا الوجه. العبارة صحيحة.", "c": "2024", "k": "geo"},
{"q": "في الشكل المرسوم AECDBHGF متوازي مستطيلات فيه ABC قائم في A، و HE = 1 و EC = 4 و HB = 3. العبارة «الطول BC يساوي √26» هي:", "opts": ["صح", "غلط، والطول 5", "غلط، والطول √17", "غلط، والطول √10"], "corr": 0, "exp": "AC² = EC² + EA² = 16 + 9 = 25 فـ AC = 5، و AB = HE = 1. في المثلث القائم ABC: BC² = AB² + AC² = 1 + 25 = 26، فـ BC = √26 والعبارة صحيحة.", "c": "2024", "k": "geo"},
{"q": "العبارة التي تُكمل (2x − .....)(..... + .....) = ...... − 25 هي:", "opts": ["(2x − 5)(2x + 5) = 4x² − 25", "(2x − 5)(2x + 5) = 2x² − 25", "(2x − 5)(2x − 5) = 4x² − 25", "(2x − 25)(2x + 1) = 4x² − 25"], "corr": 0, "exp": "الحد الأخير 25 = 5²، فنكتب فرق مربعين: (2x − 5)(2x + 5) = (2x)² − 5² = 4x² − 25.", "c": "2024", "k": "geo"},
{"q": "العدد الذي يُكمل المتطابقة 11 + 6√2 = (..... + √2)² هو:", "opts": ["3", "2", "6", "9"], "corr": 0, "exp": "(a + √2)² = a² + 2a√2 + 2. نطابق مع 11 + 6√2: 2a = 6 ⟹ a = 3، والتحقق: 9 + 2 = 11.", "c": "2024", "k": "factor"},
{"q": "أسطوانة دورانية ارتفاعها h = 4 cm ونصف قطر قاعدتها r = 3 cm، فإن حجمها V بوحدة cm³ يساوي:", "opts": ["36π", "24π", "48π", "72π"], "corr": 0, "exp": "V = π × r² × h = π × 9 × 4 = 36π cm³.", "c": "2024", "k": "solids"},
{"q": "أسطوانة دورانية ارتفاعها h = 4 cm ونصف قطر قاعدتها r = 3 cm، فإن مساحة سطحها الجانبي بوحدة cm² تساوي:", "opts": ["24π", "36π", "18π", "12π"], "corr": 0, "exp": "المساحة الجانبية = 2 × π × r × h = 2 × π × 3 × 4 = 24π cm².", "c": "2024", "k": "solids"},
{"q": "ليكن التابعان f و g المعرّفان بالعلاقتين f(x) = (2x − 3)(2x + 1) و g(x) = (2x − 3)² + 8x − 12. قيمة f(3/2) تساوي:", "opts": ["0", "−4", "4", "−3"], "corr": 0, "exp": "f(3/2) = (2 × 3/2 − 3)(2 × 3/2 + 1) = (3 − 3)(3 + 1) = 0 × 4 = 0.", "c": "2024", "k": "functions"},
{"q": "ليكن التابعان f و g المعرّفان بالعلاقتين f(x) = (2x − 3)(2x + 1) و g(x) = (2x − 3)² + 8x − 12. قيمة g(−1/2) تساوي:", "opts": ["0", "−12", "16", "−4"], "corr": 0, "exp": "g(−1/2) = (−1 − 3)² + 8 × (−1/2) − 12 = 16 − 4 − 12 = 0.", "c": "2024", "k": "functions"},
{"q": "ليكن التابعان f و g المعرّفان بالعلاقتين f(x) = (2x − 3)(2x + 1) و g(x) = (2x − 3)² + 8x − 12. نشر g(x) واختزاله يعطي:", "opts": ["4x² − 4x − 3", "4x² − 12x + 9", "4x² + 4x − 3", "4x² − 4x + 21"], "corr": 0, "exp": "(2x − 3)² = 4x² − 12x + 9، فـ g(x) = 4x² − 12x + 9 + 8x − 12 = 4x² − 4x − 3.", "c": "2024", "k": "factor"},
{"q": "ليكن التابعان f و g المعرّفان بالعلاقتين f(x) = (2x − 3)(2x + 1) و g(x) = (2x − 3)² + 8x − 12. تحليل g(x) إلى جداء عاملين من الدرجة الأولى يعطي:", "opts": ["(2x − 3)(2x + 1)", "(2x − 3)(2x − 1)", "(2x + 3)(2x + 1)", "(2x − 3)²"], "corr": 0, "exp": "g(x) = (2x − 3)² + 4(2x − 3) = (2x − 3)[(2x − 3) + 4] = (2x − 3)(2x + 1).", "c": "2024", "k": "factor"},
{"q": "ليكن التابعان f و g المعرّفان بالعلاقتين f(x) = (2x − 3)(2x + 1) و g(x) = (2x − 3)² + 8x − 12. نستنتج أن f(x) = g(x)، وحلول المعادلة g(x) = 0 هي:", "opts": ["x = 3/2 أو x = −1/2", "x = −3/2 أو x = 1/2", "x = 3/2 أو x = 1/2", "x = 3 أو x = −1"], "corr": 0, "exp": "g(x) = (2x − 3)(2x + 1) = f(x). المعادلة (2x − 3)(2x + 1) = 0 تعطي 2x − 3 = 0 أي x = 3/2، أو 2x + 1 = 0 أي x = −1/2.", "c": "2024", "k": "equations"},
{"q": "نعتبر المتراجحة (3x + 2)/4 < 2. أي من الأعداد 0 و 5 و 6 يحقق المتراجحة وأيها ليس حلاً؟", "opts": ["0 حل، و 5 و 6 ليسا حلين", "0 و 5 حلان، و 6 ليس حلاً", "0 و 5 و 6 جميعها حلول", "0 ليس حلاً، و 5 و 6 حلان"], "corr": 0, "exp": "عند 0: (0 + 2)/4 = 0.5 < 2 صحيحة. عند 5: 17/4 = 4.25 < 2 خاطئة. عند 6: 20/4 = 5 < 2 خاطئة.", "c": "2024", "k": "equations"},
{"q": "حل المتراجحة (3x + 2)/4 < 2 هو:", "opts": ["x < 2", "x > 2", "x < 6", "x > 6"], "corr": 0, "exp": "نضرب الطرفين بـ 4: 3x + 2 < 8 ⟹ 3x < 6 ⟹ x < 2. وتُمثَّل بالنقاط على يسار العدد 2 دون العدد 2 نفسه.", "c": "2024", "k": "equations"},
{"q": "حلول المتراجحة 2 ≥ (3x − 2)/4 + 1 هي:", "opts": ["x ≤ 2", "x < 2", "x ≥ 2", "x > 2"], "corr": 0, "exp": "(3x − 2)/4 + 1 = (3x + 2)/4، فالمتراجحة هي (3x + 2)/4 ≤ 2. من المتراجحة السابقة (3x + 2)/4 < 2 تعطي x < 2، وتضاف حالة التساوي x = 2، فالحل x ≤ 2 (العدد 2 مشمول).", "c": "2024", "k": "equations"},
{"q": "مخروطان دورانيان متقابلان بالرأس S، مركزا قاعدتيهما I و K، ونصفا قطريهما [IA] و [KB]، والمستقيمان (IA) و (KB) متوازيان، و IA = 3 و KS = 8 و KB = 6 (بوحدة cm). المثلثان SIA و SKB متشابهان لأن:", "opts": ["∠ISA = ∠KSB (متقابلتان بالرأس) و ∠SIA = ∠SKB = 90°", "SI = SK", "IA = KB", "مساحتاهما متساويتان"], "corr": 0, "exp": "الزاويتان ∠ISA و ∠KSB متقابلتان بالرأس فهما متساويتان، والزاويتان ∠SIA و ∠SKB قائمتان (محور المخروط عمودي على القاعدة)، فالمثلثان متشابهان.", "c": "2024", "k": "solids"},
{"q": "مخروطان دورانيان متقابلان بالرأس S، مركزا قاعدتيهما I و K، ونصفا قطريهما [IA] و [KB]، والمستقيمان (IA) و (KB) متوازيان، و IA = 3 و KS = 8 و KB = 6 (بوحدة cm). نسب التشابه بين المثلثين SIA و SKB هي:", "opts": ["SI/SK = SA/SB = IA/KB", "SI/SB = SA/SK = IA/KB", "SI/SK = SA/SB = IA/SB", "SI/KB = SA/SK = IA/SB"], "corr": 0, "exp": "في المثلثين المتشابهين الأضلاع المتناظرة متناسبة: SI ↔ SK و SA ↔ SB و IA ↔ KB، وقيمة النسبة = IA/KB = 3/6 = 1/2.", "c": "2024", "k": "solids"},
{"q": "مخروطان دورانيان متقابلان بالرأس S، مركزا قاعدتيهما I و K، ونصفا قطريهما [IA] و [KB]، والمستقيمان (IA) و (KB) متوازيان، و IA = 3 و KS = 8 و KB = 6 (بوحدة cm). طول SB يساوي:", "opts": ["10 cm", "14 cm", "√28 cm", "12 cm"], "corr": 0, "exp": "المثلث SKB قائم في K: SB² = SK² + KB² = 64 + 36 = 100 ⟹ SB = 10 cm.", "c": "2024", "k": "solids"},
{"q": "مخروطان دورانيان متقابلان بالرأس S، مركزا قاعدتيهما I و K، ونصفا قطريهما [IA] و [KB]، والمستقيمان (IA) و (KB) متوازيان، و IA = 3 و KS = 8 و KB = 6 (بوحدة cm). طول SI يساوي:", "opts": ["4 cm", "3 cm", "5 cm", "16 cm"], "corr": 0, "exp": "SI/SK = IA/KB = 3/6 = 1/2 ⟹ SI = 8 × 1/2 = 4 cm.", "c": "2024", "k": "solids"},
{"q": "مخروطان دورانيان متقابلان بالرأس S، مركزا قاعدتيهما I و K، ونصفا قطريهما [IA] و [KB]، والمستقيمان (IA) و (KB) متوازيان، و IA = 3 و KS = 8 و KB = 6 (بوحدة cm). طول SA يساوي:", "opts": ["5 cm", "4 cm", "6 cm", "3 cm"], "corr": 0, "exp": "SA/SB = 1/2 ⟹ SA = 10 × 1/2 = 5 cm. (تحقق: SA² = SI² + IA² = 16 + 9 = 25).", "c": "2024", "k": "solids"},
{"q": "مخروطان دورانيان متقابلان بالرأس S، مركزا قاعدتيهما I و K، ونصفا قطريهما [IA] و [KB]، والمستقيمان (IA) و (KB) متوازيان، و IA = 3 و KS = 8 و KB = 6 (بوحدة cm). قيمة tan(∠KSB) تساوي:", "opts": ["3/4", "4/3", "3/5", "4/5"], "corr": 0, "exp": "في المثلث القائم SKB: tan(∠KSB) = KB / KS = 6/8 = 3/4.", "c": "2024", "k": "solids"},
{"q": "مخروطان دورانيان متقابلان بالرأس S، مركزا قاعدتيهما I و K، ونصفا قطريهما [IA] و [KB]، والمستقيمان (IA) و (KB) متوازيان، و IA = 3 و KS = 8 و KB = 6 (بوحدة cm). حجم المخروط الذي مركز قاعدته K (ارتفاعه SK) هو v₂ ويساوي:", "opts": ["96π cm³", "288π cm³", "48π cm³", "192π cm³"], "corr": 0, "exp": "v₂ = ⅓ × π × KB² × SK = ⅓ × π × 36 × 8 = 96π cm³.", "c": "2024", "k": "solids"},
{"q": "مخروطان دورانيان متقابلان بالرأس S، مركزا قاعدتيهما I و K، ونصفا قطريهما [IA] و [KB]، والمستقيمان (IA) و (KB) متوازيان، و IA = 3 و KS = 8 و KB = 6 (بوحدة cm). المخروط الذي مركز قاعدته I وحجمه v₁ هو تصغير للمخروط الذي مركز قاعدته K وحجمه v₂، فإن النسبة v₁/v₂ تساوي:", "opts": ["1/8", "1/2", "1/4", "1/6"], "corr": 0, "exp": "نسبة التصغير k = 1/2، ونسبة الحجمين = k³ = 1/8. (تحقق: v₁ = ⅓π × 9 × 4 = 12π و 12π/96π = 1/8).", "c": "2024", "k": "solids"},
{"q": "كيس فيه 12 كرة متماثلة مرقمة S = (1 , 1 , 1 , 1 , 2 , 2 , 2 , 2 , 2 , 2 , 3 , 5)، تُسحب منه كرة عشوائياً ويُقرأ رقمها. احتمالات ظهور الأرقام 1 و 2 و 3 و 5 على الترتيب (على فروع شجرة الإمكانات) هي:", "opts": ["4/12 , 6/12 , 1/12 , 1/12", "4/12 , 5/12 , 1/12 , 2/12", "3/12 , 6/12 , 1/12 , 2/12", "1/4 , 1/4 , 1/4 , 1/4"], "corr": 0, "exp": "عدد الكرات 12: أربع كرات تحمل 1 وست كرات تحمل 2 وكرة واحدة تحمل 3 وكرة واحدة تحمل 5، ومجموع الاحتمالات = 12/12 = 1.", "c": "2024", "k": "stats"},
{"q": "كيس فيه 12 كرة متماثلة مرقمة S = (1 , 1 , 1 , 1 , 2 , 2 , 2 , 2 , 2 , 2 , 3 , 5)، تُسحب منه كرة عشوائياً ويُقرأ رقمها. احتمال الحدث A: «سحب كرة تحمل رقماً أكبر تماماً من 2» يساوي:", "opts": ["1/6", "1/2", "1/12", "5/6"], "corr": 0, "exp": "الأرقام الأكبر تماماً من 2 هي 3 و 5، وعدد الكرات التي تحملها 2 من 12، فـ P(A) = 2/12 = 1/6.", "c": "2024", "k": "stats"},
{"q": "المدى للعينة S = (1 , 1 , 1 , 1 , 2 , 2 , 2 , 2 , 2 , 2 , 3 , 5) يساوي:", "opts": ["4", "5", "3", "2"], "corr": 0, "exp": "المدى = أكبر قيمة − أصغر قيمة = 5 − 1 = 4.", "c": "2024", "k": "stats"},
{"q": "المتوسط الحسابي للعينة S = (1 , 1 , 1 , 1 , 2 , 2 , 2 , 2 , 2 , 2 , 3 , 5) يساوي:", "opts": ["2", "2.5", "1.5", "3"], "corr": 0, "exp": "المجموع = 4×1 + 6×2 + 3 + 5 = 4 + 12 + 8 = 24، والمتوسط = 24 ÷ 12 = 2.", "c": "2024", "k": "stats"},
{"q": "الوسيط للعينة S = (1 , 1 , 1 , 1 , 2 , 2 , 2 , 2 , 2 , 2 , 3 , 5) يساوي:", "opts": ["2", "1.5", "2.5", "3"], "corr": 0, "exp": "عدد القيم 12 (زوجي)، والقيمتان الوسطيتان (السادسة والسابعة) كلتاهما 2، فالوسيط = (2 + 2) ÷ 2 = 2.", "c": "2024", "k": "stats"},
{"q": "لتكن جملة المعادلتين d: x + y = 6 و Δ: 3x + 4y = 12. حل الجملة هو:", "opts": ["(x , y) = (12 , −6)", "(x , y) = (6 , 0)", "(x , y) = (−12 , 6)", "(x , y) = (4 , 2)"], "corr": 0, "exp": "من d: x = 6 − y، نعوض في Δ: 3(6 − y) + 4y = 12 ⟹ 18 + y = 12 ⟹ y = −6 ثم x = 12.", "c": "2024", "k": "equations"},
{"q": "النقطتان اللتان تنتميان إلى المستقيم d: x + y = 6 هما:", "opts": ["A(6 , 0) و B(0 , 6)", "M(4 , 0) و N(0 , 3)", "A(6 , 0) و N(0 , 3)", "B(0 , 6) و M(4 , 0)"], "corr": 0, "exp": "A: 6 + 0 = 6 ✓، B: 0 + 6 = 6 ✓. أما M: 4 + 0 = 4 ≠ 6 و N: 0 + 3 = 3 ≠ 6.", "c": "2024", "k": "functions"},
{"q": "النقطتان اللتان تنتميان إلى المستقيم Δ: 3x + 4y = 12 هما:", "opts": ["M(4 , 0) و N(0 , 3)", "A(6 , 0) و B(0 , 6)", "A(6 , 0) و N(0 , 3)", "B(0 , 6) و M(4 , 0)"], "corr": 0, "exp": "M: 3×4 + 0 = 12 ✓، N: 0 + 4×3 = 12 ✓. أما A: 18 ≠ 12 و B: 24 ≠ 12.", "c": "2024", "k": "functions"},
{"q": "إذا كانت A(6 , 0) و B(0 , 6) و M(4 , 0) و N(0 , 3)، فإن مساحة الرباعي BNMA بوحدة المساحة تساوي:", "opts": ["12", "18", "6", "24"], "corr": 0, "exp": "مساحة الرباعي = مساحة المثلث OAB − مساحة المثلث OMN = ½×6×6 − ½×4×3 = 18 − 6 = 12.", "c": "2024", "k": "triangle"},
{"q": "A و B و C و D أربع نقاط من دائرة مركزها O، الوتران [AB] و [CD] متعامدان في E، و ∠BCD = 65°، و [EF] متوسط في المثلث CEB (F منتصف [CB])، والمستقيم (EF) يقطع (AD) في I. قياس القوس BD يساوي:", "opts": ["130°", "65°", "115°", "90°"], "corr": 0, "exp": "∠BCD زاوية محيطية تحصر القوس BD، فقياس القوس = 2 × 65° = 130°.", "c": "2024", "k": "stats"},
{"q": "A و B و C و D أربع نقاط من دائرة مركزها O، الوتران [AB] و [CD] متعامدان في E، و ∠BCD = 65°، و [EF] متوسط في المثلث CEB (F منتصف [CB])، والمستقيم (EF) يقطع (AD) في I. قياس الزاوية ∠DAB يساوي:", "opts": ["65°", "130°", "25°", "115°"], "corr": 0, "exp": "∠DAB زاوية محيطية تحصر القوس BD نفسه، فقياسها = 130° ÷ 2 = 65° (وتساوي ∠BCD).", "c": "2024", "k": "stats"},
{"q": "A و B و C و D أربع نقاط من دائرة مركزها O، الوتران [AB] و [CD] متعامدان في E، و ∠BCD = 65°، و [EF] متوسط في المثلث CEB (F منتصف [CB])، والمستقيم (EF) يقطع (AD) في I. قياس الزاوية ∠EBC يساوي:", "opts": ["25°", "65°", "35°", "45°"], "corr": 0, "exp": "المثلث CEB قائم في E لأن (AB) ⟂ (CD)، و ∠ECB = ∠DCB = 65°، فـ ∠EBC = 90° − 65° = 25°.", "c": "2024", "k": "stats"},
{"q": "A و B و C و D أربع نقاط من دائرة مركزها O، الوتران [AB] و [CD] متعامدان في E، و ∠BCD = 65°، و [EF] متوسط في المثلث CEB (F منتصف [CB])، والمستقيم (EF) يقطع (AD) في I. طبيعة المثلث EFC هي:", "opts": ["متساوي الساقين رأسه F", "متساوي الأضلاع", "قائم في F", "قائم في E"], "corr": 0, "exp": "EF متوسط المتعلق بالوتر في المثلث القائم CEB، وطوله نصف الوتر: EF = FC = FB. فالمثلث EFC متساوي الساقين رأسه F.", "c": "2024", "k": "stats"},
{"q": "A و B و C و D أربع نقاط من دائرة مركزها O، الوتران [AB] و [CD] متعامدان في E، و ∠BCD = 65°، و [EF] متوسط في المثلث CEB (F منتصف [CB])، والمستقيم (EF) يقطع (AD) في I. قياس الزاوية ∠CEF يساوي:", "opts": ["65°", "25°", "45°", "90°"], "corr": 0, "exp": "المثلث EFC متساوي الساقين رأسه F فـ ∠CEF = ∠ECF = ∠ECB = 65°.", "c": "2024", "k": "stats"},
{"q": "A و B و C و D أربع نقاط من دائرة مركزها O، الوتران [AB] و [CD] متعامدان في E، و ∠BCD = 65°، و [EF] متوسط في المثلث CEB (F منتصف [CB])، والمستقيم (EF) يقطع (AD) في I. قياس الزاوية ∠IEA يساوي:", "opts": ["25°", "65°", "90°", "35°"], "corr": 0, "exp": "∠IEA = ∠FEB (متقابلتان بالرأس)، و ∠FEB = ∠CEB − ∠CEF = 90° − 65° = 25°.", "c": "2024", "k": "stats"},
{"q": "A و B و C و D أربع نقاط من دائرة مركزها O، الوتران [AB] و [CD] متعامدان في E، و ∠BCD = 65°، و [EF] متوسط في المثلث CEB (F منتصف [CB])، والمستقيم (EF) يقطع (AD) في I. المستقيمان (AD) و (EI) متعامدان لأن:", "opts": ["في المثلث AEI: ∠IAE = 65° و ∠IEA = 25° فـ ∠AIE = 90°", "∠AEI = 90°", "AD = EI", "∠DAB = ∠IEA"], "corr": 0, "exp": "في المثلث AIE: ∠IAE = ∠DAB = 65° و ∠IEA = 25°، فمجموعهما 90°، وبالتالي ∠AIE = 180° − 90° = 90°، أي (AD) ⊥ (EI).", "c": "2024", "k": "stats"},
{"q": "القاسم المشترك الأكبر للعددين 18 و 35 هو:", "opts": ["1", "3", "7", "9"], "corr": 0, "exp": "18 = 2 × 3² و 35 = 5 × 7، ولا يوجد بينهما عامل أولي مشترك، فالقاسم المشترك الأكبر 1 (عددان أوليان فيما بينهما).", "c": "2023", "k": "powers"},
{"q": "ناتج sin 45° + cos 45° يساوي:", "opts": ["√2", "2", "1", "√2/2"], "corr": 0, "exp": "sin 45° = cos 45° = √2/2، فالمجموع = √2/2 + √2/2 = √2.", "c": "2023", "k": "triangle"},
{"q": "ناتج (2⁵ × 2⁻³ × 3²) ÷ (2² × 3⁻¹) يساوي:", "opts": ["27", "16", "9", "4"], "corr": 0, "exp": "البسط = 2⁵⁻³ × 3² = 4 × 9 = 36، والمقام = 4 × 3⁻¹ = 4/3. الناتج = 36 ÷ (4/3) = 27. وبطريقة الأسس: 2^(2−2) × 3^(2+1) = 3³ = 27.", "c": "2023", "k": "powers"},
{"q": "إذا كان احتمال الحدث A يساوي 1/3، فإن احتمال الحدث المعاكس A′ يساوي:", "opts": ["2/3", "1", "−2/3", "1/3"], "corr": 0, "exp": "P(A′) = 1 − P(A) = 1 − 1/3 = 2/3.", "c": "2023", "k": "stats"},
{"q": "العبارة «وسيط العينة 10 , 12 , 10 , 5 , 4 , 3 هو العدد 5» هي:", "opts": ["غلط، والوسيط الصحيح 7.5", "صح، والوسيط 5", "غلط، والوسيط الصحيح 10", "غلط، والوسيط الصحيح 7"], "corr": 0, "exp": "نرتب القيم: 3 , 4 , 5 , 10 , 10 , 12. عددها 6 (زوجي)، فالوسيط = (5 + 10) ÷ 2 = 7.5، فالعبارة خاطئة.", "c": "2023", "k": "stats"},
{"q": "العبارة «العدد √20 / √5 هو عدد طبيعي» هي:", "opts": ["صح، لأنه يساوي 2", "غلط، لأنه يساوي √4 وهو غير عادي", "غلط، لأنه يساوي √15", "غلط، لأنه يساوي 4"], "corr": 0, "exp": "√20 / √5 = √(20/5) = √4 = 2، وهو عدد طبيعي، فالعبارة صحيحة.", "c": "2023", "k": "powers"},
{"q": "العبارة «مقطع المخروط الدوراني بمستوٍ يوازي قاعدته هو دائرة» هي:", "opts": ["صح", "غلط، المقطع قطع ناقص", "غلط، المقطع مثلث", "غلط، المقطع مستطيل"], "corr": 0, "exp": "المقطع الموازي لقاعدة المخروط الدوراني دائرة مركزها على محور المخروط، وهي تصغير لقاعدته. العبارة صحيحة.", "c": "2023", "k": "solids"},
{"q": "العبارة «حجم مكعب طول حرفه 4 cm يساوي 16 cm²» هي:", "opts": ["غلط، والحجم 64 cm³", "صح، والحجم 16 cm²", "غلط، والحجم 16 cm³", "غلط، والحجم 48 cm³"], "corr": 0, "exp": "حجم المكعب = a³ = 4³ = 64 cm³، ووحدة الحجم cm³ وليست cm²، فالعبارة خاطئة.", "c": "2023", "k": "solids"},
{"q": "ABCD مستطيل بعداه AB = √7 + 2 و BC = √7 − 2، و EFGH مربع طول ضلعه √27 − 2√3. نكتب √27 − 2√3 بالشكل √a حيث a عدد طبيعي، فإن a تساوي:", "opts": ["3", "15", "12", "27"], "corr": 0, "exp": "√27 = √(9 × 3) = 3√3، فـ √27 − 2√3 = 3√3 − 2√3 = √3، إذن a = 3.", "c": "2023", "k": "geo"},
{"q": "ABCD مستطيل بعداه AB = √7 + 2 و BC = √7 − 2، و EFGH مربع طول ضلعه √27 − 2√3. مساحة المستطيل ومساحة المربع هما على الترتيب:", "opts": ["3 و 3", "3 و 9", "11 و 3", "7 و 3"], "corr": 0, "exp": "مساحة المستطيل = (√7 + 2)(√7 − 2) = 7 − 4 = 3. ضلع المربع = √3، فمساحته (√3)² = 3.", "c": "2023", "k": "geo"},
{"q": "ABCD مستطيل بعداه AB = √7 + 2 و BC = √7 − 2، و EFGH مربع طول ضلعه √27 − 2√3. المقارنة بين مساحتي المستطيل والمربع تعطي:", "opts": ["المساحتان متساويتان", "مساحة المستطيل أكبر", "مساحة المربع أكبر", "لا يمكن المقارنة"], "corr": 0, "exp": "مساحة المستطيل = 3 ومساحة المربع = 3، فالمساحتان متساويتان.", "c": "2023", "k": "geo"},
{"q": "ADE مثلث متساوي الأضلاع طول ضلعه 3 مرسوم في دائرة مركزها O، و (CE) و (CD) مماسان للدائرة في E و D. قياس الزاوية ∠DOE (وهو أيضاً قياس القوس DE) يساوي:", "opts": ["120°", "60°", "90°", "30°"], "corr": 0, "exp": "∠DAE = 60° زاوية محيطية تحصر القوس DE، والزاوية المركزية المقابلة ∠DOE = 2 × 60° = 120°، وقياس القوس DE = 120°.", "c": "2023", "k": "circle"},
{"q": "ADE مثلث متساوي الأضلاع طول ضلعه 3 مرسوم في دائرة مركزها O، و (CE) و (CD) مماسان للدائرة في E و D. قياسات زوايا المثلث DEC هي:", "opts": ["∠CDE = ∠CED = ∠DCE = 60°", "∠CDE = ∠CED = 30° و ∠DCE = 120°", "∠CDE = ∠CED = 45° و ∠DCE = 90°", "∠CDE = ∠CED = 50° و ∠DCE = 80°"], "corr": 0, "exp": "الزاوية بين المماس والوتر تساوي نصف القوس الذي تحصره: ∠CDE = ∠CED = 120° ÷ 2 = 60°، فـ ∠DCE = 180° − 120° = 60° (أو من الرباعي ODCE: 360° − 90° − 90° − 120° = 60°).", "c": "2023", "k": "circle"},
{"q": "ADE مثلث متساوي الأضلاع طول ضلعه 3 مرسوم في دائرة مركزها O، و (CE) و (CD) مماسان للدائرة في E و D. محيط الرباعي AECD يساوي:", "opts": ["12", "9", "15", "6"], "corr": 0, "exp": "AE = AD = 3 (ضلعا المثلث ADE)، و EC = CD = DE = 3 لأن المثلث DEC متساوي الأضلاع وضلعه DE = 3. المحيط = 3 + 3 + 3 + 3 = 12.", "c": "2023", "k": "circle"},
{"q": "ADE مثلث متساوي الأضلاع طول ضلعه 3 مرسوم في دائرة مركزها O، و (CE) و (CD) مماسان للدائرة في E و D. نوع الرباعي AECD هو:", "opts": ["معين", "مربع", "مستطيل", "شبه منحرف"], "corr": 0, "exp": "أضلاعه الأربعة متساوية (كل منها 3) وزواياه غير قائمة (∠DCE = 60°)، فهو معين.", "c": "2023", "k": "circle"},
{"q": "لدينا المقدار B = (3x + 1)(x − 5) − (3x + 1)². نشر B واختزاله يعطي:", "opts": ["−6x² − 20x − 6", "6x² − 20x − 6", "−6x² − 20x + 6", "−6x² − 8x − 6"], "corr": 0, "exp": "(3x + 1)(x − 5) = 3x² − 14x − 5 و (3x + 1)² = 9x² + 6x + 1، فـ B = 3x² − 14x − 5 − 9x² − 6x − 1 = −6x² − 20x − 6.", "c": "2023", "k": "factor"},
{"q": "لدينا المقدار B = (3x + 1)(x − 5) − (3x + 1)². تحليل B إلى جداء عاملين يعطي:", "opts": ["−2(3x + 1)(x + 3)", "2(3x + 1)(x + 3)", "(3x + 1)(x − 5)", "−2(3x + 1)(x − 3)"], "corr": 0, "exp": "نأخذ (3x + 1) عاملاً مشتركاً: B = (3x + 1)[(x − 5) − (3x + 1)] = (3x + 1)(−2x − 6) = −2(3x + 1)(x + 3).", "c": "2023", "k": "factor"},
{"q": "لدينا المقدار B = (3x + 1)(x − 5) − (3x + 1)². حلول المعادلة B = 0 هي:", "opts": ["x = −1/3 أو x = −3", "x = 1/3 أو x = 3", "x = −1/3 أو x = 3", "x = 1/3 أو x = −3"], "corr": 0, "exp": "−2(3x + 1)(x + 3) = 0 ⟹ 3x + 1 = 0 أي x = −1/3، أو x + 3 = 0 أي x = −3.", "c": "2023", "k": "equations"},
{"q": "ليكن f تابعاً معرّفاً بالعلاقة f(x) = x² − 1. قيمة f(0) تساوي:", "opts": ["−1", "1", "0", "−2"], "corr": 0, "exp": "f(0) = 0² − 1 = −1.", "c": "2023", "k": "functions"},
{"q": "ليكن f تابعاً معرّفاً بالعلاقة f(x) = x² − 1. قيمة f(−√2) تساوي:", "opts": ["1", "−1", "3", "2 − √2"], "corr": 0, "exp": "f(−√2) = (−√2)² − 1 = 2 − 1 = 1.", "c": "2023", "k": "functions"},
{"q": "ليكن f تابعاً معرّفاً بالعلاقة f(x) = x² − 1. أسلاف العدد 8 هي:", "opts": ["3 و −3", "3 فقط", "9 و −9", "√7 و −√7"], "corr": 0, "exp": "نحل f(x) = 8: x² − 1 = 8 ⟹ x² = 9 ⟹ x = 3 أو x = −3.", "c": "2023", "k": "functions"},
{"q": "حل المتراجحة 3x − 1 < 2x − 2 هو:", "opts": ["x < −1", "x > −1", "x < 1", "x > 1"], "corr": 0, "exp": "3x − 2x < −2 + 1 ⟹ x < −1. وتُمثَّل الحلول على مستقيم الأعداد بالنقاط التي تقع على يسار العدد −1 دون العدد −1 نفسه.", "c": "2023", "k": "equations"},
{"q": "ABC مثلث، M و N نقطتان من [AB] و [AC] على الترتيب بحيث CB = 3 و MB = 1.9 و MA = 2.1 و CN = 19/8 و NA = 21/8. المثلث ABC قائم في B لأن:", "opts": ["AB² + BC² = AC² (عكس مبرهنة فيثاغورث)", "AB = BC", "AC أصغر الأضلاع", "AB + BC = AC"], "corr": 0, "exp": "AB = MB + MA = 1.9 + 2.1 = 4، و AC = CN + NA = 19/8 + 21/8 = 5. نجد: AB² + BC² = 16 + 9 = 25 = AC²، فالمثلث قائم في B.", "c": "2023", "k": "triangle"},
{"q": "ABC مثلث، M و N نقطتان من [AB] و [AC] على الترتيب بحيث CB = 3 و MB = 1.9 و MA = 2.1 و CN = 19/8 و NA = 21/8. المستقيمان (MN) و (CB) متوازيان لأن:", "opts": ["AM/AB = AN/AC (عكس مبرهنة طالس)", "AM = AN", "MB = CN", "∠B = ∠C"], "corr": 0, "exp": "AM/AB = 2.1/4 = 21/40، و AN/AC = (21/8)/5 = 21/40. النسبتان متساويتان والنقاط A و M و B وكذلك A و N و C على استقامة واحدة بالترتيب نفسه، فحسب عكس مبرهنة طالس (MN) // (CB).", "c": "2023", "k": "triangle"},
{"q": "المستقيم Δ: x + y = 0 يمر بمبدأ الإحداثيات O(0 , 0) لأن:", "opts": ["إحداثيي O يحققان معادلته (0 + 0 = 0)", "ميله يساوي 1", "معادلته تحوي الحد x فقط", "يقطع محور التراتيب في 2"], "corr": 0, "exp": "نعوض إحداثيي O في معادلة Δ: 0 + 0 = 0 فالمساواة محققة، إذن Δ يمر بالمبدأ.", "c": "2023", "k": "functions"},
{"q": "حل جملة المعادلتين Δ: x + y = 0 و d: x − y = −2 هو:", "opts": ["(x , y) = (−1 , 1)", "(x , y) = (1 , −1)", "(x , y) = (−1 , −1)", "(x , y) = (1 , 1)"], "corr": 0, "exp": "بجمع المعادلتين: 2x = −2 ⟹ x = −1، ثم من x + y = 0 نجد y = 1. وهما إحداثيا N نقطة تقاطع Δ و d.", "c": "2023", "k": "equations"},
{"q": "إحداثيا النقطة A نقطة تقاطع المستقيم d: x − y = −2 مع محور التراتيب هما:", "opts": ["A(0 , 2)", "A(0 , −2)", "A(2 , 0)", "A(−2 , 0)"], "corr": 0, "exp": "على محور التراتيب x = 0، فيكون −y = −2 أي y = 2، إذن A(0 , 2).", "c": "2023", "k": "functions"},
{"q": "إذا كانت O(0 , 0) و A(0 , 2) و N(−1 , 1)، فإن مساحة المثلث NOA بوحدة المساحة تساوي:", "opts": ["1", "2", "0.5", "1.5"], "corr": 0, "exp": "نأخذ القاعدة OA = 2 على محور التراتيب، والارتفاع المقابل = بعد N عن المحور = 1. المساحة = ½ × 2 × 1 = 1.", "c": "2023", "k": "triangle"},
{"q": "نصف دائرة مركزها O وقطرها [AB] طوله 8، N نقطة منها بحيث القوس AN = 2 × القوس NB، و MAB مثلث متساوي الساقين وقائم في A، و I منتصف [MB] و H منتصف [MA]. قياس القوس NB يساوي:", "opts": ["60°", "30°", "90°", "120°"], "corr": 0, "exp": "نصف الدائرة 180° = القوس AN + القوس NB = 2 × NB + NB = 3 × NB، فقياس القوس NB = 60° والقوس AN = 120°.", "c": "2023", "k": "circle"},
{"q": "نصف دائرة مركزها O وقطرها [AB] طوله 8، N نقطة منها بحيث القوس AN = 2 × القوس NB، و MAB مثلث متساوي الساقين وقائم في A، و I منتصف [MB] و H منتصف [MA]. قياس الزاوية ∠NAB يساوي:", "opts": ["30°", "60°", "45°", "120°"], "corr": 0, "exp": "∠NAB زاوية محيطية تحصر القوس NB الذي قياسه 60°، فقياسها 60° ÷ 2 = 30°.", "c": "2023", "k": "circle"},
{"q": "نصف دائرة مركزها O وقطرها [AB] طوله 8، N نقطة منها بحيث القوس AN = 2 × القوس NB، و MAB مثلث متساوي الساقين وقائم في A، و I منتصف [MB] و H منتصف [MA]. طول NB يساوي:", "opts": ["4", "4√3", "8", "2"], "corr": 0, "exp": "المثلث ONB فيه OB = ON = 4 والزاوية المركزية ∠NOB = 60°، فهو متساوي الأضلاع وNB = 4. (أو: ANB قائم في N و ∠NAB = 30° فـ NB = AB/2 = 4).", "c": "2023", "k": "circle"},
{"q": "نصف دائرة مركزها O وقطرها [AB] طوله 8، N نقطة منها بحيث القوس AN = 2 × القوس NB، و MAB مثلث متساوي الساقين وقائم في A، و I منتصف [MB] و H منتصف [MA]. طول NA يساوي:", "opts": ["4√3", "4", "8√3", "6"], "corr": 0, "exp": "المثلث ANB قائم في N (محيطي يحصر قطراً): NA² = AB² − NB² = 64 − 16 = 48، فـ NA = √48 = 4√3.", "c": "2023", "k": "circle"},
{"q": "نصف دائرة مركزها O وقطرها [AB] طوله 8، N نقطة منها بحيث القوس AN = 2 × القوس NB، و MAB مثلث متساوي الساقين وقائم في A، و I منتصف [MB] و H منتصف [MA]. الرباعي ANBI رباعي دائري لأن:", "opts": ["∠ANB = ∠AIB = 90° فالنقطتان N و I تقعان على الدائرة التي قطرها AB", "∠NAB = ∠IAB", "AN = NB", "IA = IB = 8"], "corr": 0, "exp": "∠ANB = 90° لأن N على الدائرة التي قطرها AB، و ∠AIB = 90° لأن AI متوسط وارتفاع في المثلث MAB المتساوي الساقين. فالنقطتان N و I تريان القطعة AB بزاوية قائمة، فتقعان على الدائرة التي قطرها AB.", "c": "2023", "k": "circle"},
{"q": "نصف دائرة مركزها O وقطرها [AB] طوله 8، N نقطة منها بحيث القوس AN = 2 × القوس NB، و MAB مثلث متساوي الساقين وقائم في A، و I منتصف [MB] و H منتصف [MA]. مساحة المنطقة المظللة (المحصورة بين الوتر AN والقوس AN) بوحدة المساحة تساوي:", "opts": ["16π/3 − 4√3", "16π/3 + 4√3", "16π/3", "8π − 4√3"], "corr": 0, "exp": "المساحة = مساحة القطاع الدائري OAN − مساحة المثلث OAN. القطاع زاويته 120°: (120/360) × π × 4² = 16π/3. المثلث OAN: ½ × 4 × 4 × sin 120° = 4√3. فالمساحة = 16π/3 − 4√3 (≈ 9.83).", "c": "2023", "k": "circle"},
{"q": "العدد (3⁷ × 2⁸) ÷ (9³ × 2⁵) يساوي:", "opts": ["24", "26", "12", "48"], "corr": 0, "exp": "9³ = (3²)³ = 3⁶، فالعدد = 3⁷⁻⁶ × 2⁸⁻⁵ = 3 × 2³ = 3 × 8 = 24.", "c": "2022", "k": "powers"},
{"q": "الكسر المختزل المساوي للكسر 130/520 هو:", "opts": ["1/4", "1/2", "1/8", "1/3"], "corr": 0, "exp": "نقسم البسط والمقام على 130: 130 ÷ 130 = 1 و 520 ÷ 130 = 4، فالكسر المختزل 1/4.", "c": "2022", "k": "powers"},
{"q": "المعادلة التي تقبل x = −2 حلاً لها هي:", "opts": ["5x + 2 = 3x − 2", "x² + 4 = 0", "3x + 1 = 2x", "2x + 4 = 2"], "corr": 0, "exp": "نعوض x = −2 في 5x + 2 = 3x − 2: الطرف الأول −10 + 2 = −8 والثاني −6 − 2 = −8، فالمساواة محققة. أما 3x + 1 = 2x فتعطي −5 ≠ −4، و x² + 4 = 0 لا حل لها، و 2x + 4 = 2 تعطي 0 ≠ 2.", "c": "2022", "k": "equations"},
{"q": "العدد √(3 + 2√2) يساوي:", "opts": ["1 + √2", "1 − √2", "5√2", "3 + √2"], "corr": 0, "exp": "(1 + √2)² = 1 + 2√2 + 2 = 3 + 2√2، وبما أن 1 + √2 موجب فإن √(3 + 2√2) = 1 + √2.", "c": "2022", "k": "powers"},
{"q": "العبارة «مقطع مكعب بمستوٍ يوازي أحد أوجهه هو مربع» هي:", "opts": ["صح", "غلط، المقطع مستطيل غير مربع", "غلط، المقطع مثلث", "غلط، المقطع دائرة"], "corr": 0, "exp": "المقطع الموازي لأحد أوجه المكعب يطابق ذلك الوجه، وهو مربع. العبارة صحيحة.", "c": "2022", "k": "solids"},
{"q": "العبارة «cos 80° = sin 20°» هي:", "opts": ["غلط، لأن cos 80° = sin 10°", "صح", "غلط، لأن cos 80° = sin 80°", "غلط، لأن cos 80° = sin 70°"], "corr": 0, "exp": "cos(90° − x) = sin x، فـ cos 80° = sin 10° وهي لا تساوي sin 20°، فالعبارة خاطئة.", "c": "2022", "k": "triangle"},
{"q": "العبارة «العدد √3 هو حل للمعادلة x² − 3 = 0» هي:", "opts": ["صح", "غلط، لأن (√3)² − 3 = 3", "غلط، لأن (√3)² − 3 = −3", "غلط، لأن √3 غير عادي"], "corr": 0, "exp": "نعوض: (√3)² − 3 = 3 − 3 = 0، فالمساواة محققة والعبارة صحيحة (وكذلك −√3 حل للمعادلة).", "c": "2022", "k": "equations"},
{"q": "العبارة «إذا كانت الزاوية Â تحقق 0° < Â < 90° فإن 0 < sin Â < 1» هي:", "opts": ["صح", "غلط، لأن sin Â قد تساوي 1", "غلط، لأن sin Â قد تكون سالبة", "غلط، لأن sin Â أكبر من 1"], "corr": 0, "exp": "لأي زاوية حادة تكون نسبة الضلع المقابل إلى الوتر موجبة وأصغر من 1 (الضلع المقابل أقصر من الوتر)، فالعبارة صحيحة.", "c": "2022", "k": "triangle"},
{"q": "لدينا المقدار E = (x − 1)² − 4. نشر E واختزاله يعطي:", "opts": ["x² − 2x − 3", "x² + 2x − 3", "x² − 2x + 5", "x² − 5"], "corr": 0, "exp": "(x − 1)² = x² − 2x + 1، فـ E = x² − 2x + 1 − 4 = x² − 2x − 3.", "c": "2022", "k": "factor"},
{"q": "لدينا المقدار E = (x − 1)² − 4. تحليل E إلى جداء عاملين يعطي:", "opts": ["(x − 3)(x + 1)", "(x − 3)(x − 1)", "(x + 3)(x − 1)", "(x − 5)(x + 3)"], "corr": 0, "exp": "E فرق مربعين: (x − 1)² − 2² = (x − 1 − 2)(x − 1 + 2) = (x − 3)(x + 1).", "c": "2022", "k": "factor"},
{"q": "لدينا المقدار E = (x − 1)² − 4. حلول المعادلة E = −3 هي:", "opts": ["x = 0 أو x = 2", "x = 3 أو x = −1", "x = 0 أو x = −2", "x = 1 أو x = 3"], "corr": 0, "exp": "E = −3 ⟹ x² − 2x − 3 = −3 ⟹ x² − 2x = 0 ⟹ x(x − 2) = 0 ⟹ x = 0 أو x = 2.", "c": "2022", "k": "equations"},
{"q": "التابع f ممثل بيانياً بالخط البياني المجاور، ويمر منحناه بالنقطة التي فاصلتها 0 وترتيبها −1 (أخفض نقطة). قيمة f(0) تساوي:", "opts": ["−1", "0", "1", "2"], "corr": 0, "exp": "قيمة f(0) هي ترتيب النقطة التي فاصلتها 0 على المنحني، ومن الرسم هي −1.", "c": "2022", "k": "circle"},
{"q": "التابع f ممثل بيانياً بالخط البياني المجاور، وأعلى نقطة على منحناه فاصلتها 3 وترتيبها 2. قيمة f(3) تساوي:", "opts": ["2", "3", "1", "0"], "corr": 0, "exp": "قيمة f(3) هي ترتيب النقطة التي فاصلتها 3 على المنحني، ومن الرسم هي 2.", "c": "2022", "k": "circle"},
{"q": "حل المتراجحة 2x − 1 ≤ 7 هو:", "opts": ["x ≤ 4", "x ≥ 4", "x ≤ 3", "x ≥ 3"], "corr": 0, "exp": "2x ≤ 7 + 1 ⟹ 2x ≤ 8 ⟹ x ≤ 4. وتُمثَّل الحلول على مستقيم الأعداد بالنقاط التي تقع على يسار العدد 4 مع العدد 4 نفسه.", "c": "2022", "k": "equations"},
{"q": "صندوق فيه 5 بطاقات متماثلة كُتبت عليها الأرقام 4 , 4 , 3 , 2 , 2، تُسحب منه بطاقة عشوائياً ويُقرأ رقمها. احتمالات ظهور الأرقام 4 و 3 و 2 على الترتيب (على فروع شجرة الإمكانات) هي:", "opts": ["2/5 , 1/5 , 2/5", "1/3 , 1/3 , 1/3", "2/5 , 2/5 , 1/5", "1/5 , 2/5 , 2/5"], "corr": 0, "exp": "البطاقات 5: بطاقتان تحملان 4، وبطاقة واحدة تحمل 3، وبطاقتان تحملان 2، ومجموع الاحتمالات = 5/5 = 1.", "c": "2022", "k": "stats"},
{"q": "صندوق فيه 5 بطاقات متماثلة كُتبت عليها الأرقام 4 , 4 , 3 , 2 , 2، تُسحب منه بطاقة عشوائياً ويُقرأ رقمها. احتمال الحدث A: «سحب بطاقة تحمل رقماً أصغر تماماً من 4» يساوي:", "opts": ["3/5", "2/5", "1/5", "4/5"], "corr": 0, "exp": "الأرقام الأصغر تماماً من 4 هي 3 و 2 و 2 أي 3 بطاقات من 5، فـ P(A) = 3/5.", "c": "2022", "k": "stats"},
{"q": "صندوق فيه 5 بطاقات متماثلة كُتبت عليها الأرقام 4 , 4 , 3 , 2 , 2، تُسحب منه بطاقة عشوائياً ويُقرأ رقمها. احتمال الحدث المعاكس A′ للحدث A: «سحب بطاقة تحمل رقماً أصغر تماماً من 4» يساوي:", "opts": ["2/5", "3/5", "1/5", "1"], "corr": 0, "exp": "P(A′) = 1 − P(A) = 1 − 3/5 = 2/5 (وهو احتمال سحب بطاقة تحمل الرقم 4).", "c": "2022", "k": "stats"},
{"q": "وسيط العينة 4 , 4 , 3 , 2 , 2 يساوي:", "opts": ["3", "2", "4", "3.5"], "corr": 0, "exp": "نرتب القيم: 2 , 2 , 3 , 4 , 4. عددها 5 (فردي)، فالوسيط هو القيمة الوسطى = 3.", "c": "2022", "k": "stats"},
{"q": "في الشكل المجاور المخروط ς رأسه A وارتفاعه AB = 6 وقاعدته الدائرة التي مركزها B ونصف قطرها BC = 3. طول AC يساوي:", "opts": ["3√5", "√27", "9", "√45 + 3"], "corr": 0, "exp": "المثلث ABC قائم في B: AC² = AB² + BC² = 36 + 9 = 45 ⟹ AC = √45 = 3√5.", "c": "2022", "k": "solids"},
{"q": "في الشكل المجاور المخروط ς رأسه A وارتفاعه AB = 6 وقاعدته الدائرة التي مركزها B ونصف قطرها BC = 3. قيمة tan(∠ACB) تساوي:", "opts": ["2", "1/2", "√5", "2√5"], "corr": 0, "exp": "في المثلث القائم ABC: tan(∠ACB) = AB / BC = 6/3 = 2.", "c": "2022", "k": "solids"},
{"q": "في الشكل المجاور المخروط ς رأسه A وارتفاعه AB = 6 وقاعدته الدائرة التي مركزها B ونصف قطرها BC = 3. مساحة قاعدة المخروط S تساوي:", "opts": ["9π", "3π", "6π", "18π"], "corr": 0, "exp": "S = π × r² = π × 3² = 9π.", "c": "2022", "k": "solids"},
{"q": "في الشكل المجاور المخروط ς رأسه A وارتفاعه AB = 6 وقاعدته الدائرة التي مركزها B ونصف قطرها BC = 3. حجم المخروط V يساوي:", "opts": ["18π", "54π", "9π", "36π"], "corr": 0, "exp": "V = ⅓ × S × h = ⅓ × 9π × 6 = 18π.", "c": "2022", "k": "solids"},
{"q": "ABC مثلث فيه ∠C = 45° و Â/B̂ = 1/2 و AB = 2. مجموع القياسين Â + B̂ يساوي:", "opts": ["135°", "45°", "90°", "180°"], "corr": 0, "exp": "مجموع زوايا المثلث 180°، فـ Â + B̂ = 180° − 45° = 135°.", "c": "2022", "k": "triangle"},
{"q": "ABC مثلث فيه ∠C = 45° و Â/B̂ = 1/2 و AB = 2. قياسا الزاويتين Â و B̂ هما:", "opts": ["Â = 45° و B̂ = 90°", "Â = 90° و B̂ = 45°", "Â = 60° و B̂ = 75°", "Â = 30° و B̂ = 60°"], "corr": 0, "exp": "Â/B̂ = 1/2 فـ B̂ = 2Â، ومنه Â + 2Â = 135° ⟹ Â = 45° و B̂ = 90°.", "c": "2022", "k": "triangle"},
{"q": "ABC مثلث فيه ∠C = 45° و Â/B̂ = 1/2 و AB = 2. طول AC يساوي:", "opts": ["2√2", "2", "4", "√2"], "corr": 0, "exp": "المثلث ABC قائم في B و ∠A = ∠C = 45°، فهو متساوي الساقين BC = AB = 2، و AC² = 4 + 4 = 8 ⟹ AC = 2√2. (أو: sin C = AB / AC ⟹ AC = 2 ÷ (√2/2) = 2√2).", "c": "2022", "k": "triangle"},
{"q": "المستقيمان (d₁) و (d₂) معادلتاهما d₁: y = 2x + 2 و d₂: 3x − y + 3 = 0. حل جملة المعادلتين هو:", "opts": ["(x , y) = (−1 , 0)", "(x , y) = (1 , 0)", "(x , y) = (0 , 2)", "(x , y) = (−1 , 2)"], "corr": 0, "exp": "من d₂: y = 3x + 3. بمساواة المعادلتين: 2x + 2 = 3x + 3 ⟹ x = −1، ثم y = 2(−1) + 2 = 0. وهما إحداثيا نقطة التقاطع A(−1 , 0).", "c": "2022", "k": "equations"},
{"q": "المستقيمان (d₁) و (d₂) معادلتاهما d₁: y = 2x + 2 و d₂: 3x − y + 3 = 0. إحداثيا النقطة B نقطة تقاطع (d₁) مع محور التراتيب هما:", "opts": ["B(0 , 2)", "B(0 , −2)", "B(−1 , 0)", "B(2 , 0)"], "corr": 0, "exp": "على محور التراتيب x = 0، فيكون y = 2(0) + 2 = 2، إذن B(0 , 2).", "c": "2022", "k": "functions"},
{"q": "المستقيمان (d₁) و (d₂) معادلتاهما d₁: y = 2x + 2 و d₂: 3x − y + 3 = 0. إحداثيا النقطة C نقطة تقاطع (d₂) مع محور التراتيب هما:", "opts": ["C(0 , 3)", "C(0 , −3)", "C(−1 , 0)", "C(3 , 0)"], "corr": 0, "exp": "على محور التراتيب x = 0، فيكون −y + 3 = 0 أي y = 3، إذن C(0 , 3).", "c": "2022", "k": "functions"},
{"q": "دائرتان متماستان داخلاً في النقطة A: C₁ مركزها O ونصف قطرها 6 وقطرها [AB]، و C₂ مركزها O′ وقطرها [AM] حيث AM = 4، والمستقيم (MN) مماس للدائرة C₂ في M، وقياس القوس BC هو 60° (C نقطة من C₁)، و E نقطة تقاطع C₂ مع [AC]، و N نقطة تقاطع (MN) مع (AC). المثلث ABC قائم في C لأن:", "opts": ["C نقطة من دائرة قطرها [AB]", "AB = 12", "∠BAC = 30°", "AC = BC"], "corr": 0, "exp": "كل مثلث مرسوم داخل دائرة وأحد أضلاعه قطر لها يكون قائماً في الرأس المقابل لذلك الضلع، فالمثلث ABC قائم في C، أي ∠ACB = 90°.", "c": "2022", "k": "circle"},
{"q": "دائرتان متماستان داخلاً في النقطة A: C₁ مركزها O ونصف قطرها 6 وقطرها [AB]، و C₂ مركزها O′ وقطرها [AM] حيث AM = 4، والمستقيم (MN) مماس للدائرة C₂ في M، وقياس القوس BC هو 60° (C نقطة من C₁)، و E نقطة تقاطع C₂ مع [AC]، و N نقطة تقاطع (MN) مع (AC). قياس الزاوية ∠BAC يساوي:", "opts": ["30°", "60°", "45°", "120°"], "corr": 0, "exp": "∠BAC زاوية محيطية تحصر القوس BC الذي قياسه 60°، فقياسها 60° ÷ 2 = 30°.", "c": "2022", "k": "circle"},
{"q": "دائرتان متماستان داخلاً في النقطة A: C₁ مركزها O ونصف قطرها 6 وقطرها [AB]، و C₂ مركزها O′ وقطرها [AM] حيث AM = 4، والمستقيم (MN) مماس للدائرة C₂ في M، وقياس القوس BC هو 60° (C نقطة من C₁)، و E نقطة تقاطع C₂ مع [AC]، و N نقطة تقاطع (MN) مع (AC). طول BC يساوي:", "opts": ["6", "6√3", "12", "3"], "corr": 0, "exp": "AB = 12 والمثلث ABC قائم في C: BC = AB × sin 30° = 12 × ½ = 6.", "c": "2022", "k": "circle"},
{"q": "دائرتان متماستان داخلاً في النقطة A: C₁ مركزها O ونصف قطرها 6 وقطرها [AB]، و C₂ مركزها O′ وقطرها [AM] حيث AM = 4، والمستقيم (MN) مماس للدائرة C₂ في M، وقياس القوس BC هو 60° (C نقطة من C₁)، و E نقطة تقاطع C₂ مع [AC]، و N نقطة تقاطع (MN) مع (AC). طول AC يساوي:", "opts": ["6√3", "6", "12√3", "3√3"], "corr": 0, "exp": "AC = AB × cos 30° = 12 × √3/2 = 6√3. (تحقق: AC² = 144 − 36 = 108).", "c": "2022", "k": "circle"},
{"q": "دائرتان متماستان داخلاً في النقطة A: C₁ مركزها O ونصف قطرها 6 وقطرها [AB]، و C₂ مركزها O′ وقطرها [AM] حيث AM = 4، والمستقيم (MN) مماس للدائرة C₂ في M، وقياس القوس BC هو 60° (C نقطة من C₁)، و E نقطة تقاطع C₂ مع [AC]، و N نقطة تقاطع (MN) مع (AC). المستقيمان (ME) و (BC) متوازيان لأن:", "opts": ["كلاً منهما عمودي على (AC)", "ME = BC", "∠EAM = ∠CAB فقط", "AM = MB"], "corr": 0, "exp": "∠AEM = 90° لأنها محيطية في C₂ تحصر القطر [AM]، فـ (ME) ⟂ (AC). و ∠ACB = 90° فـ (BC) ⟂ (AC). المستقيمان العموديان على (AC) متوازيان، فتنطبق مبرهنة النسب الثلاث (طالس) على المثلثين AME و ABC.", "c": "2022", "k": "circle"},
{"q": "دائرتان متماستان داخلاً في النقطة A: C₁ مركزها O ونصف قطرها 6 وقطرها [AB]، و C₂ مركزها O′ وقطرها [AM] حيث AM = 4، والمستقيم (MN) مماس للدائرة C₂ في M، وقياس القوس BC هو 60° (C نقطة من C₁)، و E نقطة تقاطع C₂ مع [AC]، و N نقطة تقاطع (MN) مع (AC). النسب الثلاث المتساوية في المثلثين AME و ABC هي:", "opts": ["AM/AB = AE/AC = ME/BC", "AM/AB = AE/AC = ME/AC", "AM/AE = AB/AC = ME/BC", "AM/BC = AE/AC = ME/AB"], "corr": 0, "exp": "بما أن (ME) // (BC) فالأضلاع المتناظرة متناسبة: AM ↔ AB و AE ↔ AC و ME ↔ BC، وقيمة النسبة AM/AB = 4/12 = 1/3.", "c": "2022", "k": "circle"},
{"q": "دائرتان متماستان داخلاً في النقطة A: C₁ مركزها O ونصف قطرها 6 وقطرها [AB]، و C₂ مركزها O′ وقطرها [AM] حيث AM = 4، والمستقيم (MN) مماس للدائرة C₂ في M، وقياس القوس BC هو 60° (C نقطة من C₁)، و E نقطة تقاطع C₂ مع [AC]، و N نقطة تقاطع (MN) مع (AC). طول ME يساوي:", "opts": ["2", "4", "3", "6"], "corr": 0, "exp": "ME/BC = AM/AB = 1/3 ⟹ ME = 6 ÷ 3 = 2.", "c": "2022", "k": "circle"},
{"q": "دائرتان متماستان داخلاً في النقطة A: C₁ مركزها O ونصف قطرها 6 وقطرها [AB]، و C₂ مركزها O′ وقطرها [AM] حيث AM = 4، والمستقيم (MN) مماس للدائرة C₂ في M، وقياس القوس BC هو 60° (C نقطة من C₁)، و E نقطة تقاطع C₂ مع [AC]، و N نقطة تقاطع (MN) مع (AC). الرباعي CNMB رباعي دائري لأن:", "opts": ["∠NMB = ∠NCB = 90° وتحصران القطعة NB", "∠NCB = ∠NMB = 60°", "CN = NM", "BC = BM"], "corr": 0, "exp": "(MN) ⟂ (AB) لأنه مماس لـ C₂ عند M (طرف القطر AM)، فـ ∠NMB = 90°. و ∠NCB = ∠ACB = 90°. فالنقطتان M و C تريان القطعة NB بزاوية قائمة، فتقعان على الدائرة التي قطرها NB، فالرباعي دائري ومركز دائرته منتصف [NB].", "c": "2022", "k": "circle"},
{"q": "دائرتان متماستان داخلاً في النقطة A: C₁ مركزها O ونصف قطرها 6 وقطرها [AB]، و C₂ مركزها O′ وقطرها [AM] حيث AM = 4، والمستقيم (MN) مماس للدائرة C₂ في M، وقياس القوس BC هو 60° (C نقطة من C₁)، و E نقطة تقاطع C₂ مع [AC]، و N نقطة تقاطع (MN) مع (AC). مركز الدائرة المارة برؤوس الرباعي CNMB هو:", "opts": ["منتصف القطعة [NB]", "النقطة O", "النقطة O′", "منتصف القطعة [CM]"], "corr": 0, "exp": "الزاويتان القائمتان في M و C تحصران القطعة [NB]، فهي قطر الدائرة المارة بالرؤوس، ومركزها منتصف [NB].", "c": "2022", "k": "circle"},
{"q": "دائرتان متماستان داخلاً في النقطة A: C₁ مركزها O ونصف قطرها 6 وقطرها [AB]، و C₂ مركزها O′ وقطرها [AM] حيث AM = 4، والمستقيم (MN) مماس للدائرة C₂ في M، وقياس القوس BC هو 60° (C نقطة من C₁)، و E نقطة تقاطع C₂ مع [AC]، و N نقطة تقاطع (MN) مع (AC). قياس الزاوية ∠NME يساوي:", "opts": ["30°", "60°", "45°", "90°"], "corr": 0, "exp": "في المثلث AME القائم في E و ∠EAM = 30°: ∠AME = 60°. وبما أن ∠AMN = 90° فإن ∠NME = 90° − 60° = 30°.", "c": "2022", "k": "circle"}
